// Generated by scripts/split-game.mjs: this site serves one game at `#/`. The game's own sources still call
// navigate() with portfolio routes (Home, the hub); those leave for the portfolio site.
import { useEffect, useState } from 'react'
import { parse as parseFull, type Route } from './router.base'

export type { Route }

const GAME = 'sports'
export const PORTFOLIO_URL = 'https://shreyansh-sharan.github.io/shreyanshsharan-portfolio/'

/** `#/`, `#/?auto=...` and `#/sports?...` all mean the game; only the query matters. */
export function parse(hash: string): Route {
  const query = hash.includes('?') ? hash.slice(hash.indexOf('?')) : ''
  return parseFull(`#/${GAME}${query}`)
}

export function navigate(to: string) {
  if (parseFull(to).name === GAME) {
    const query = to.includes('?') ? to.slice(to.indexOf('?')) : ''
    const next = `#/${query}`
    if (window.location.hash !== next) window.location.hash = next
    return
  }
  window.location.assign(PORTFOLIO_URL + to)
}

export function useRoute(): Route {
  const [route, setRoute] = useState(() => parse(window.location.hash))
  useEffect(() => {
    const onChange = () => setRoute(parse(window.location.hash))
    window.addEventListener('hashchange', onChange)
    return () => window.removeEventListener('hashchange', onChange)
  }, [])
  return route
}
